import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.BU4O3IzQ.js";const u=JSON.parse('{"title":"AI 动态 · 2026-08-05","description":"","frontmatter":{"title":"AI 动态 · 2026-08-05","date":"2026-08-05T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-05.md","filePath":"news/2026-08/ai-news-2026-08-05.md","lastUpdated":1786092171000}'),i={name:"news/2026-08/ai-news-2026-08-05.md"};function r(o,e,l,p,c,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-08-05" tabindex="-1">AI 动态 · 2026-08-05 <a class="header-anchor" href="#ai-动态-·-2026-08-05" aria-label="Permalink to &quot;AI 动态 · 2026-08-05&quot;">​</a></h1><blockquote><p>截至 2026-08-05。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="微软叫停tokenmaxxing-设置ai-token预算-内部默认模型切换为gpt-5-6" tabindex="-1">微软叫停Tokenmaxxing：设置AI Token预算，内部默认模型切换为GPT-5.6 <a class="header-anchor" href="#微软叫停tokenmaxxing-设置ai-token预算-内部默认模型切换为gpt-5-6" aria-label="Permalink to &quot;微软叫停Tokenmaxxing：设置AI Token预算，内部默认模型切换为GPT-5.6&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-05">2026-08-05</time></p><p>微软自2026年7月起为各业务部门设置AI Token预算目标，并将内部默认模型切换为更便宜的GPT-5.6。执行副总裁Jay Parikh在内部邮件中强调，员工应像管理其他关键资源一样管理token花费，并可视个人token支出。此前CEO纳德拉曾承认自己也是Tokenmaxxer，但如今强调生产率的边际收益必须匹配token的边际成本。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/466739.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="亚马逊云科技发布guardduty-investigation-agent-ai驱动的安全调查工具" tabindex="-1">亚马逊云科技发布GuardDuty Investigation Agent：AI驱动的安全调查工具 <a class="header-anchor" href="#亚马逊云科技发布guardduty-investigation-agent-ai驱动的安全调查工具" aria-label="Permalink to &quot;亚马逊云科技发布GuardDuty Investigation Agent：AI驱动的安全调查工具&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-05">2026-08-05</time></p><p><img src="https://static001.infoq.cn/resource/image/06/2a/06e0307a9014e38ee207081189b2f22a.jpg" alt="配图"></p><p>亚马逊云科技发布Amazon GuardDuty Investigation Agent公共预览版，这是一款AI驱动的安全工具，可评估安全发现、关联历史活动并映射威胁遥测数据。它支持发现分析、账户分析和组织分析三种范围，将调查流程从数小时缩短至数分钟，并生成包含风险等级、置信度评分和可执行修复步骤的结构化报告。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/YZEahCZsDt3lZhHYvLPX?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai回应第三方网络安全评估事件-公布新防护措施" tabindex="-1">OpenAI回应第三方网络安全评估事件，公布新防护措施 <a class="header-anchor" href="#openai回应第三方网络安全评估事件-公布新防护措施" aria-label="Permalink to &quot;OpenAI回应第三方网络安全评估事件，公布新防护措施&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-08-05">2026-08-05</time></p><p><img src="https://images.ctfassets.net/kftzwdyauwt9/6RSPaWdKwEvT9xWx4IjQy2/a334438e4daf9f62c24541c00c212749/third-party-cyber-evaluations_16x9.png?w=1600&amp;h=900&amp;fit=fill" alt="配图"></p><p>OpenAI发文解释近期涉及第三方网络安全评估的事故，并概述了新的防护措施。在两次外部测试中，测试配置与控制措施结合新模型的能力提升，导致模型活动超出了预期测试边界。OpenAI强调独立测试对部署前验证风险的重要性，并将加强第三方模型评估环境的安全性。</p><p class="news-entry-source"><a href="https://openai.com/index/third-party-cyber-evaluations-involving-openai-models" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="sand-ai开源全球首个千亿moe视频生成模型magi-2-preview-114b参数仅激活6b" tabindex="-1">Sand.ai开源全球首个千亿MoE视频生成模型MAGI-2-preview：114B参数仅激活6B <a class="header-anchor" href="#sand-ai开源全球首个千亿moe视频生成模型magi-2-preview-114b参数仅激活6b" aria-label="Permalink to &quot;Sand.ai开源全球首个千亿MoE视频生成模型MAGI-2-preview：114B参数仅激活6B&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-05">2026-08-05</time></p><p>清华系团队Sand.ai开源视频生成模型MAGI-2-preview，总参数114B，单次前向仅激活约6B。生成10秒1080P视频成本约5毛钱，仅为行业主流模型的十分之一。该模型在AA视频生成榜单排名第六，效果接近第一梯队。其采用MoE架构解决视频模型Scaling的训推成本问题，但需应对通信和训练稳定性挑战。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/466847.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="minimax-h3视频模型上线秘塔ai-2k方案0-15元-秒-768p低至0-09元-秒" tabindex="-1">MiniMax H3视频模型上线秘塔AI：2K方案0.15元/秒，768P低至0.09元/秒 <a class="header-anchor" href="#minimax-h3视频模型上线秘塔ai-2k方案0-15元-秒-768p低至0-09元-秒" aria-label="Permalink to &quot;MiniMax H3视频模型上线秘塔AI：2K方案0.15元/秒，768P低至0.09元/秒&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-05">2026-08-05</time></p><p>MiniMax H3视频模型在秘塔AI平台上线，用户无需部署即可直接使用。2K方案价格为0.15元/秒，768P方案低至0.09元/秒，生成5秒视频成本不到5毛钱。该模型是MiniMax首个开源视频模型，在Artificial Analysis榜单视频编辑排名第一，支持原生双声道音视频、2K分辨率、文字信息呈现和动作迁移等能力。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/467036.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="gpt-5-6价格暴降-luna降80-至-0-20-1-20-auto-review成本降10倍" tabindex="-1">GPT-5.6价格暴降：Luna降80%至$0.20/$1.20，Auto-review成本降10倍 <a class="header-anchor" href="#gpt-5-6价格暴降-luna降80-至-0-20-1-20-auto-review成本降10倍" aria-label="Permalink to &quot;GPT-5.6价格暴降：Luna降80%至$0.20/$1.20，Auto-review成本降10倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-05">2026-08-05</time></p><p><img src="https://static001.infoq.cn/resource/image/3d/02/3d100d357536dd7310d060244d8e0f02.jpg" alt="配图"></p><p>OpenAI宣布GPT-5.6系列大降价，入门款Luna价格下调80%，定价每百万输入token 0.20美元、输出1.20美元；Terra下调20%至$2/$12。Luna性能媲美一年前前沿模型，单位任务成本约6美分，速度提升近9倍。ChatGPT和Codex CLI的Auto-review已升级至Luna，预计成本降低约10倍。降价源于GPU内核优化和推测性解码改进。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/KROGtjyegHRSKCSNS70o?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="addyosmani-agent-skills-面向ai编码智能体的生产级工程技能库" tabindex="-1">addyosmani/agent-skills：面向AI编码智能体的生产级工程技能库 <a class="header-anchor" href="#addyosmani-agent-skills-面向ai编码智能体的生产级工程技能库" aria-label="Permalink to &quot;addyosmani/agent-skills：面向AI编码智能体的生产级工程技能库&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">addyosmani/agent-skills</span><time datetime="2026-08-05">2026-08-05</time></p><p><img src="https://opengraph.githubassets.com/1/addyosmani/agent-skills" alt="配图"></p><p>Google Chrome团队工程师Addy Osmani开源了agent-skills项目，提供面向AI编码智能体的生产级工程技能。该项目旨在帮助AI编码工具更好地理解和执行真实世界的工程任务，涵盖代码审查、测试、性能优化等场景，可作为AI Agent的技能增强库使用。</p><p class="news-entry-source"><a href="https://github.com/addyosmani/agent-skills" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="loopx-面向长期运行ai-agent团队的轻量级循环工程状态内核" tabindex="-1">loopx：面向长期运行AI Agent团队的轻量级循环工程状态内核 <a class="header-anchor" href="#loopx-面向长期运行ai-agent团队的轻量级循环工程状态内核" aria-label="Permalink to &quot;loopx：面向长期运行AI Agent团队的轻量级循环工程状态内核&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">huangruiteng/loopx</span><time datetime="2026-08-05">2026-08-05</time></p><p><img src="https://opengraph.githubassets.com/1/huangruiteng/loopx" alt="配图"></p><p>huangruiteng/loopx是一个轻量级循环工程状态内核，专为长期运行的AI Agent团队设计。它支持Codex、Claude Code等多种编码Agent，提供持久化目标、配额感知自动唤醒、可执行待办事项、证据日志和可验证交接等功能，帮助管理复杂的多Agent协作流程。</p><p class="news-entry-source"><a href="https://github.com/huangruiteng/loopx" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github教你用stacked-pr将巨型ai生成pr拆解为可审查的提交栈" tabindex="-1">GitHub教你用Stacked PR将巨型AI生成PR拆解为可审查的提交栈 <a class="header-anchor" href="#github教你用stacked-pr将巨型ai生成pr拆解为可审查的提交栈" aria-label="Permalink to &quot;GitHub教你用Stacked PR将巨型AI生成PR拆解为可审查的提交栈&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-08-05">2026-08-05</time></p><p><img src="https://github.blog/wp-content/uploads/2026/01/generic-mona-github.png" alt="配图"></p><p>GitHub官方博客发布指南，教授如何利用GitHub Stacked Pull Requests功能，将AI生成的一个巨大且难以审查的PR，拆解为干净、有序的提交栈。该方法有助于提高代码审查效率和质量，尤其适合AI编码Agent生成大量代码的场景。</p><p class="news-entry-source"><a href="https://github.blog/engineering/turn-one-giant-ai-generated-pull-request-to-a-reviewable-stack/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="github法务团队用copilot-cli简化工作流-不写一行代码构建工具" tabindex="-1">GitHub法务团队用Copilot CLI简化工作流：不写一行代码构建工具 <a class="header-anchor" href="#github法务团队用copilot-cli简化工作流-不写一行代码构建工具" aria-label="Permalink to &quot;GitHub法务团队用Copilot CLI简化工作流：不写一行代码构建工具&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-08-05">2026-08-05</time></p><p>GitHub博客分享了其法务团队如何使用Copilot CLI来简化工作流程的案例。该团队通过自然语言与AI助手交互，构建了自动化工具，无需编写任何代码即可完成重复性任务，展示了非技术团队利用AI提升效率的实践路径。</p><p class="news-entry-source"><a href="https://github.blog/ai-and-ml/github-copilot/how-the-github-legal-team-used-copilot-cli-to-streamline-their-workflows/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
